import dgbtf2 = require( './index' );


// TESTS //

const AB = new Float64Array( 3 );
const PIV = new Int32Array( 3 );

// Numeric status is separate from positive 1-based stepwise pivots:
dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, PIV ); // $ExpectType number
dgbtf2( 'column-major', 3, 3, 0, 0, AB, 3, PIV ); // $ExpectType number
dgbtf2( 101, 3, 3, 0, 0, AB, 3, PIV ); // $ExpectType number
dgbtf2( 102, 3, 3, 0, 0, AB, 3, PIV ); // $ExpectType number
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV, -1, 2 ); // $ExpectType number

// Incorrect enums and array roles are rejected:
dgbtf2( 103, 3, 3, 0, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'upper', 3, 3, 0, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, PIV, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, AB ); // $ExpectError

// Each required argument and the exact arity have declared types:
dgbtf2( false, 3, 3, 0, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', false, 3, 0, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, false, 0, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, false, 0, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, false, AB, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, false, 3, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB, false, PIV ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, false ); // $ExpectError
dgbtf2(); // $ExpectError
dgbtf2( 'row-major' ); // $ExpectError
dgbtf2( 'row-major', 3 ); // $ExpectError
dgbtf2( 'row-major', 3, 3 ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0 ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0 ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3 ); // $ExpectError
dgbtf2( 'row-major', 3, 3, 0, 0, AB, 3, PIV, 0 ); // $ExpectError

// Each required argument and the exact arity have declared types:
dgbtf2.ndarray( false, 3, 0, 0, AB, 1, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, false, 0, 0, AB, 1, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, false, 0, AB, 1, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, false, AB, 1, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, false, 1, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, false, -1, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, false, 2, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, false, PIV, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, false, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV, false, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV, -1, false ); // $ExpectError
dgbtf2.ndarray(); // $ExpectError
dgbtf2.ndarray( 3 ); // $ExpectError
dgbtf2.ndarray( 3, 3 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV, -1 ); // $ExpectError
dgbtf2.ndarray( 3, 3, 0, 0, AB, 1, -1, 2, PIV, -1, 2, 0 ); // $ExpectError
